sys_script_include.script:
var EvSolicitarInformacoesAjax = Class.create();

EvSolicitarInformacoesAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

        solicitar: function() {
            var recordId = this.getParameter(
                'sysparm_record_id'
            );
            var message = String(
                this.getParameter('sysparm_message') || ''
            ).trim();

            if (message.length < 20) {
                return this._error(
                    'A mensagem deve ter pelo menos 20 caracteres.'
                );
            }

            var record = new GlideRecordSecure(
                'x_fub_fundbrad_ev_atendimento_ev'
            );

            if (!record.get(recordId) || !record.canWrite()) {
                return this._error(
                    'Registro inexistente ou sem permissão.'
                );
            }

            if (
                record.getValue('u_origem') !== 'escola_virtual' ||
                record.getValue('state') !== '2' ||
                record.getValue('assigned_to') !== gs.getUserID()
            ) {
                return this._error(
                    'O atendimento não está disponível para esta ação.'
                );
            }

            if (!gs.hasRole('x_fub_fundbrad_ev.agent')) {
                return this._error('Usuário não autorizado.');
            }

            record.setValue('comments', message);
            record.setValue('state', '-5');
            record.setValue('substate', 'pending_requester');

            gs.info(
                'EV BEFORE UPDATE: state=' +
                record.getValue('state') +
                ' | substate=' +
                record.getValue('substate')
            );

            var updatedId = record.update();

            if (!updatedId) {
                gs.error('EV: Falha ao atualizar atendimento ' + recordId);

                return this._error(
                    'Não foi possível atualizar o atendimento.'
                );
            }

            var verification = new GlideRecordSecure(
                'x_fub_fundbrad_ev_atendimento_ev'
            );

            if (!verification.get(recordId)) {
                return this._error('Não foi possível verificar o atendimento.');
            }

            gs.info(
                'EV: Estado após update: ' +
                verification.getValue('state') +
                ' | Substate: ' +
                verification.getValue('substate')
            );

            gs.eventQueue(
                'x_fub_fundbrad_ev.atendimento.informacao',
                record,
                record.getValue('u_email_solicitante'),
                message
            );

            return JSON.stringify({ success: true });
        },

        _error: function(message) {
            return JSON.stringify({
                success: false,
                error: message
            });
        },

        type: 'EvSolicitarInformacoesAjax'
    });
